def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from fractions import Fraction

    jump = {a: b for a, b in jumps}
    destination = list(range(n + 1))

    for start in jump:
        path = []
        cell = start
        while cell in jump and destination[cell] == cell:
            path.append(cell)
            cell = jump[cell]
        end = destination[cell]
        for cell in path:
            destination[cell] = end

    transitions = {}
    reachable = {0}
    stack = [0]

    while stack:
        cell = stack.pop()
        counts = {}
        for roll in range(1, m + 1):
            target = cell + roll
            if target > n:
                target = 2 * n - target
            target = destination[target]
            counts[target] = counts.get(target, 0) + 1
            if target != n and target not in reachable:
                reachable.add(target)
                stack.append(target)
        transitions[cell] = counts

    reverse = {cell: [] for cell in reachable}
    can_finish = set()
    stack = []

    for cell, counts in transitions.items():
        if n in counts:
            can_finish.add(cell)
            stack.append(cell)
        for target in counts:
            if target != n:
                reverse[target].append(cell)

    while stack:
        cell = stack.pop()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                stack.append(previous)

    if len(can_finish) != len(reachable):
        return None

    states = sorted(reachable)
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for cell in states:
        i = index[cell]
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    previous_pivot = 1
    for col in range(size - 1):
        pivot = matrix[col][col]
        if pivot == 0:
            for row in range(col + 1, size):
                if matrix[row][col]:
                    matrix[col], matrix[row] = matrix[row], matrix[col]
                    pivot = matrix[col][col]
                    break

        for row in range(col + 1, size):
            factor = matrix[row][col]
            for k in range(col + 1, size + 1):
                matrix[row][k] = (
                    matrix[row][k] * pivot - factor * matrix[col][k]
                ) // previous_pivot
            matrix[row][col] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for row in range(size - 1, -1, -1):
        value = Fraction(matrix[row][size])
        for col in range(row + 1, size):
            value -= matrix[row][col] * solution[col]
        solution[row] = value / matrix[row][row]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
